import type { UserRow } from "./db/users";

/**
 * Everything the Worker receives from its environment. `Env` (generated by
 * `wrangler types` from wrangler.jsonc) covers bindings and vars; secrets aren't
 * in the config file, so they're declared here by hand.
 */
export interface Bindings extends Env {
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
  /**
   * The emergency switch: "true" stops accepting notes (everything else keeps
   * working). A secret rather than a var, so it can be flipped without a
   * deploy, and a deploy doesn't flip it back. See docs/operations.md.
   */
  INGEST_PAUSED?: string;
  /** Resend's API key, for the daily digest. Without it, digests are logged, not sent. */
  RESEND_API_KEY?: string;
  /** Resend's webhook signing secret ("whsec_..."), for bounces and spam reports. */
  RESEND_WEBHOOK_SECRET?: string;
}

/** Per-request values that middleware stores on the Hono context. */
export interface Variables {
  requestId: string;
}

export interface AppEnv {
  Bindings: Bindings;
  Variables: Variables;
}

/** Routes behind `requireUser` can rely on `c.get("user")` being set. */
export interface AuthedEnv {
  Bindings: Bindings;
  Variables: Variables & { user: UserRow };
}
